class RoomServiceClientSync(ConnectClientSync):
    """
    Manages room-scoped operations for the current user.

    RoomService owns operations whose authorization and state are primarily scoped
    to one room, including lifecycle, membership, moderation, room timeline reads,
    room read state, attachments, and live typing. Resource-specific services
    should still be preferred when an operation is not naturally room-scoped or
    when the resource needs an independent CRUD/batch surface.
    """
    def get_room_read_state(
        self,
        request: GetRoomReadStateRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> GetRoomReadStateResponse:
        """
        Reads the current viewer's stored marker without changing it. Requires the
        same membership and read access as MarkRoomAsRead. Missing resources
        return NOT_FOUND; inaccessible resources return PERMISSION_DENIED.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="GetRoomReadState",
                service_name="chatto.api.v1.RoomService",
                input=GetRoomReadStateRequest,
                output=GetRoomReadStateResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def batch_get_room_read_states(
        self,
        request: BatchGetRoomReadStatesRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> BatchGetRoomReadStatesResponse:
        """
        Reads up to 100 states under the same authorization as GetRoomReadState.
        Missing and inaccessible resources are omitted; duplicates use first-seen order.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="BatchGetRoomReadStates",
                service_name="chatto.api.v1.RoomService",
                input=BatchGetRoomReadStatesRequest,
                output=BatchGetRoomReadStatesResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def create_room(
        self,
        request: CreateRoomRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> CreateRoomResponse:
        """
        Creates a new channel room in a room group. The caller must be allowed to
        create rooms in the target group.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="CreateRoom",
                service_name="chatto.api.v1.RoomService",
                input=CreateRoomRequest,
                output=CreateRoomResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def update_room(
        self,
        request: UpdateRoomRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> UpdateRoomResponse:
        """
        Updates a room's editable metadata. The caller must be allowed to manage
        rooms. Direct-message rooms cannot be universal.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="UpdateRoom",
                service_name="chatto.api.v1.RoomService",
                input=UpdateRoomRequest,
                output=UpdateRoomResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def archive_room(
        self,
        request: ArchiveRoomRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> ArchiveRoomResponse:
        """
        Archives a room so it is hidden from active room lists. The caller must be
        allowed to manage rooms.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="ArchiveRoom",
                service_name="chatto.api.v1.RoomService",
                input=ArchiveRoomRequest,
                output=ArchiveRoomResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def unarchive_room(
        self,
        request: UnarchiveRoomRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> UnarchiveRoomResponse:
        """
        Restores an archived room to active room lists. The caller must be allowed
        to manage rooms.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="UnarchiveRoom",
                service_name="chatto.api.v1.RoomService",
                input=UnarchiveRoomRequest,
                output=UnarchiveRoomResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
    def join_room(
        self,
        request: JoinRoomRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> JoinRoomResponse:
        """
        Joins the room as the current user when room permissions allow it.
        """
        return self.execute_unary(
            request=request,
            method=MethodInfo(
                name="JoinRoom",
                service_name="chatto.api.v1.RoomService",
                input=JoinRoomRequest,
                output=JoinRoomResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )
